export const SHULI_TEXTS = {
  "1": {"poem":"太極之數","keywords":["開創","獨立","富貴","名利雙收"],"text":"萬物開泰的起頭數。天地初開、一元復始，凡事從無到有皆由此始。此數之人心志獨立、主見極強，不甘居人下，凡事願自己開局而不願承舊業；早年多靠己力起家，中年後基礎漸固，名利並至。唯獨立太過則近於孤高，事事親力親為易勞身勞心，若能容人、肯授權，富貴可長保。"},
  "2": {"poem":"兩儀之數","keywords":["分離","動搖","意志不堅","勞而無功"],"text":"混沌未分的分離數。陰陽未定、進退失據，此數之人心思細而志不堅，起念多而落實少，常在兩可之間反覆，事至中途易生退意；縱有才具亦難聚力於一處，故一生波折多而成就少，家庭親緣亦每見離散。若能擇定一事守到底、少聽外言，尚可挽回三分。"},
  "3": {"poem":"三才之數","keywords":["智達","藝能","名利","早發"],"text":"陰陽調和的進取數。天地人三才俱備，智達明敏、才藝兼具，此數之人少年即顯穎悟，善解人意而人緣佳，多得長輩提攜，故早年即有發達之機；中年名利兩全，晚景亦安。唯聰明外露易招妒，須以謙和自守，方能久享。"},
  "4": {"poem":"凶變之數","keywords":["破滅","辛苦","病弱","萬事難成"],"text":"破滅衰敗的凶數。諸事不順、萬事難成，此數之人縱有才智亦難得施展之地，謀事每於將成之際生變；身體多弱、家庭緣薄，早年常見變故。非無翻身之理，然須以極大的意志與勤勉換取，且宜守成不宜投機、宜專一不宜多頭，方能稍避其鋒。"},
  "5": {"poem":"五行之數","keywords":["福祿","長壽","圓滿","家門隆昌"],"text":"陰陽交感的完璧數。五行俱全、剛柔並濟，此數之人性溫和而有主張，處事圓融不失分寸，故上下咸宜、四方逢源；福祿自來，家門隆昌，壽元亦厚，是數理中最完善的吉數之一。凡事順遂反易生怠，若能持勤守正，則終身無咎。"},
  "6": {"poem":"六爻之數","keywords":["安穩","餘慶","富貴","家運隆昌"],"text":"安穩餘慶的吉數。天德地祥兼備，此數之人多生於有根基之家，或早年得貴人之蔭，故立業不難；性情溫厚、能容人，家運隆昌而福澤綿長，晚年尤見餘慶。唯順境久則志易惰，安逸中須留一分進取，否則守得住一時守不住一世。"},
  "7": {"poem":"精悍之數","keywords":["剛毅","果斷","排除萬難","宜養柔和"],"text":"剛毅果斷的獨立數。意志剛強、精力充沛，此數之人認定一事便能排除萬難以赴，故常於逆境中反見其能，中年多有成就。然性偏剛硬、不善轉圜，與人相處每失之於直，易生嫌隙；若能涵養柔和、聽得進異見，則剛而不折，成就更大。"},
  "8": {"poem":"八卦之數","keywords":["堅忍","勤勉","有志竟成"],"text":"意志剛健的進取數。有堅忍不拔之志，能耐勞苦而貫徹始終，此數之人不以聰明取勝，而以恆心取勝，故成功雖遲而穩；中年後漸入佳境，晚運尤佳。唯過剛易折，遇事宜留轉圜之地，勿以硬碰硬耗盡元氣。"},
  "9": {"poem":"大成之數","keywords":["窮乏","逆境","物極必反"],"text":"興盡凶始的破舟數。才謀雖足而時運不濟，此數之人每有大志、亦具能力，然謀事常功敗垂成，或成而復敗，如破舟入海，力愈用而險愈近；親緣薄、身多病，中年前後尤須留意。宜守本分、宜依附有力者共事，獨當一面則易生凶險。"},
  "10": {"poem":"終結之數","keywords":["空虛","終局","破敗","萬事凋零"],"text":"萬事終局的空虛數。天賦雖厚而運途多蹇，此數之人常懷壯志卻屢遇障阻，謀事至半而基垮，一生辛勞而所得不稱；家庭亦多聚散。非全無成者，然須格外謹慎、格外惜福，且他格若得吉數相扶，尚可減其凶。"},
  "11": {"poem":"挽回之數","keywords":["再興","穩健","順調","富貴榮達"],"text":"挽回家運的春成數。草木逢春、枝葉更新，此數之人性穩而有再興之力，縱出身寒微或家道中落，亦能憑穩健經營重立門戶；財源漸進而不驟，是穩中致富之象。晚運尤厚，子孫亦得其蔭。"},
  "12": {"poem":"掘井無泉","keywords":["薄弱","孤獨","挫折","有志難伸"],"text":"意志薄弱的挫折數。家親緣薄、孤立無援，此數之人常以柔弱之力擔過重之事，力不從心而強為之，故中途多挫；心志一搖則前功盡棄，且易因過勞而損身。宜量力而行、宜借外力，不宜逞強獨撐。"},
  "13": {"poem":"春日牡丹","keywords":["智略","才藝","通達","富貴"],"text":"智略超群的博學數。天賦藝能、多才多藝，此數之人機敏善斷，臨事能於紛亂中理出頭緒，故常為眾所倚重；文藝、謀略、辯才皆有可觀，中年即見名成。唯才高者每失之於自負，須以忠厚濟之，方免招忌。"},
  "14": {"poem":"破兆之數","keywords":["破兆","孤獨","淪落","勞而無功"],"text":"破兆離散的沉淪數。家庭緣薄、孤獨悲哀，此數之人多情而少得回應，用心而少見回報，故內心常鬱；事業亦每於順境中忽生變故，如舟行遇暗礁。宜早立穩固之業、宜廣結善緣，勿使孤憤積於胸中。"},
  "15": {"poem":"福壽之數","keywords":["福壽","德望","圓滿","家門昌隆"],"text":"福壽圓滿的最大吉數。溫和恭謙、雅量厚德，此數之人以德服人而非以力壓人，故上下和順、內外咸宜；家庭圓滿、事業順遂、名利福壽俱全，是八十一數中最完滿者之一。得此數者尤宜守其厚德，德在則福在。"},
  "16": {"poem":"厚重之數","keywords":["厚德","眾望","貴人","化險為夷"],"text":"厚重載德的興家數。能得眾望、成就大業，此數之人度量寬宏，善納人言，故人才樂為所用，雖起於微而終能成大器；中年後財官並至，家門光大。唯須防因寬厚而失之於縱，用人仍當有度。"},
  "17": {"poem":"剛強之數","keywords":["剛強","權威","突破","宜養柔德"],"text":"剛強突破的權威數。意志堅定、突破萬難，此數之人一往無前，遇阻不退，故常能開出別人開不出的局面；然剛愎自用、不納人言亦是此數之病，與人每因意氣而生嫌。若能柔中帶剛、聽得進逆耳之言，則權威可久。"},
  "18": {"poem":"鐵鏡重磨","keywords":["有志竟成","積小成大","宜戒剛愎"],"text":"有志竟成的鐵石數。志向堅固、意志如鐵，此數之人一旦立志便不輕改，能於長期困頓中守住方向，故終獲權威與成功；財祿自隨，晚運尤厚。唯自尊過強、不容侵犯，易與人正面相撞，宜養涵容之量。"},
  "19": {"poem":"多難之數","keywords":["多難","障礙","病弱","成敗起伏"],"text":"風雲蔽月的破滅數。智謀雖足而遭遇不遇，此數之人常有超群之才，亦每有驚人之舉，然時運每與之相違，成敗起伏如風雲蔽月，忽明忽暗；家庭病弱、刑傷之事亦須留意。宜穩不宜急、宜守不宜攻，且當以他格之吉相濟。"},
  "20": {"poem":"屋下藏金","keywords":["破運","空虛","災難","萬事不成"],"text":"非業破運的空虛數。萬事不成、災難重重，此數之人一生多逢挫折與不測，謀事屢起屢躓，身心俱疲；病弱、破財之象亦時見於此。非無解者，然須以極穩健之姿守成，切忌投機冒進，方能保其身家。"},
  "21": {"poem":"明月中天","keywords":["獨立","權威","首領運","名利雙收"],"text":"明月中天的獨立權威數。光風霽月、萬象昭然，此數之人具首領之資，性情明朗而有決斷，故能自立門戶、漸次上達，終享名利與眾望。唯主見過強時易與人相爭，宜以柔濟剛。"},
  "22": {"poem":"秋草逢霜","keywords":["挫折","孤獨","心神過勞"],"text":"秋草逢霜的薄弱數。志向雖高而力不能副，此數之人內心敏感、外表未必示人，遇挫則傷，故常在半途生退意；身弱、家緣薄亦多見。宜擇安穩之業、宜結厚重之友，勿以孤身擔大任。"},
  "23": {"poem":"壯麗之數","keywords":["壯麗","隆昌","由微而顯","首領運"],"text":"旭日東昇的隆昌數。壯麗壯觀、旭日東昇，此數之人氣魄宏大，雖出身微賤亦能憑一己之力扶搖直上，中年即掌大權，是首領之數；財官俱盛，晚景榮華。唯盛極須防驕，剛氣太重時宜自斂。"},
  "24": {"poem":"掘藏得金","keywords":["白手成家","財源廣進"],"text":"家門餘慶的金錢數。財源廣進、白手成家，此數之人智謀出眾而擅理財，能於無中生有、由小積大，故雖起於寒素亦能積成鉅富；晚年尤豐，餘慶及於子孫。宜守其勤儉本色，勿因既富而奢。"},
  "25": {"poem":"榮俊之數","keywords":["英敏","奇才","宜修涵養","慎防口舌"],"text":"英俊剛毅的資性聰敏數。賢性銳敏、才氣奇特，此數之人多具異於常人的見識與手腕，能獲大功之運勢；然性情時有偏激一方，言語每帶諷刺，或有快性怪癖，若不加修養則易與人不和，釀成弊害。能涵養謙和，則可成功。"},
  "26": {"poem":"變怪之數","keywords":["波瀾萬丈","英雄","成敗極端"],"text":"變怪奇異的英雄數。波瀾重疊、萬難襲來，此數之人多具英雄氣概與非常才智，然一生起伏極大，或大成或大敗，少有平順者；孤獨、刑傷、破產之事亦時見。非常之人行非常之路，若能穩住心性、擇正道而行，則波瀾之後自有可觀。"},
  "27": {"poem":"增長之數","keywords":["中折","招謗","宜自制"],"text":"慾望無止的中折數。才略過人而易招誹謗，此數之人早熟而發育良好，壯年或中年即得早發之業；然自我過強，每因不肯低頭而受攻訐非難，致事業中途生折，晚來難興。設能自省其身、矯正銳氣、待人以誠，仍可避敗而自得富榮。"},
  "28": {"poem":"闊水浮萍","keywords":["遭難","變動","家屬緣薄"],"text":"闊水浮萍的遭難數。雖有豪傑之氣魄，卻如浮萍無根，一生波瀾不斷，起伏難安。此數之人多半途遭挫，家親緣薄、夫妻易離，或有刑傷病弱之憂；縱有一時之成，亦難守久。非無出路，然須擇定一處扎穩、少動少遷，方能減其凶。"},
  "29": {"poem":"智謀之數","keywords":["智謀","財力","成大業","忌貪"],"text":"智謀優秀的財力成大業數。智謀兼具、財力豐厚，此數之人有奇才亦有手腕，能於紛亂中理出機會，故中年即見大業；名利並至而聲望不小。唯慾望亦隨之而張，貪得則易生非難，也須防剛氣過盛，宜以知足自守。"},
  "30": {"poem":"非運之數","keywords":["浮沉","吉凶難分","宜守正道"],"text":"非運非命的浮沉數。吉凶難分之數，此數之人一生成敗皆極端：得意時如日中天，失意時一落千丈，全看走上哪條路。投機、僥倖之事最易招其凶；若肯守正道、走實業，則浮沉之後仍有可觀。是八十一數中最看人自身取捨的一個。"},
  "31": {"poem":"春日花開","keywords":["智勇","名望","統率","繁榮"],"text":"春日花開的智勇得志數。智仁勇三者兼備，此數之人性溫和而有統率之才，能得眾望而不失分寸，故成事不必強爭；中年後名望漸隆，事業與家門俱昌。是男女皆宜的吉數。"},
  "32": {"poem":"寶馬金鞍","keywords":["僥倖","貴人","意外之福"],"text":"僥倖多望的意外惠澤數。多得貴人提拔，往往在意外中獲得成功，如寶馬配金鞍，是承他人之力而顯達的吉數。此數之人機遇特別好，然福來自外，故須善捉機會亦須惜之；若忘恩背義，則來得快去得也快。"},
  "33": {"poem":"旭日升天","keywords":["旺盛","才德","大業"],"text":"旭日升天的鸞鳳相會數。旺盛至極之數，此數之人才德兼備、氣魄宏大，能成非常之大業，家門隆昌而名望遠播。唯物極必反，盛極須防驕；剛氣太重時與人相處易生齟齬，宜自斂以柔濟之。"},
  "34": {"poem":"破家之數","keywords":["破家","災難"],"text":"破家的大凶數。災難重疊、破家之兆，此數之人縱有才具亦難敵其運，謀事屢遭中斷，或因一事而累及全局；病弱、刑傷、家散之事皆見於此。若他格得吉數相扶尚可減輕，然終以守成、守分為上，切忌大舉大動。"},
  "35": {"poem":"溫和之數","keywords":["溫良","智達","宜文","守成"],"text":"溫良和順的智達之數。溫和平靜、智達通暢，此數之人不長於開疆拓土，而長於守成與文事；從藝、從文、從技皆有可觀，家庭亦多和順。若欲強作領袖、硬撐大局，反易生挫；安於己長，則一生平順可期。"},
  "36": {"poem":"波瀾重疊","keywords":["波瀾","俠義","沉浮","為人犧牲"],"text":"波瀾重疊的俠義之數。俠義心腸、捨己為人，此數之人重情重義，常為他人奔走而不計得失，故人緣極佳；然自身命運沉浮不定，一生難得安穩，往往成就他人而委屈自己。若能於義氣之外多留三分給自己，方免勞而無功。"},
  "37": {"poem":"權威顯達","keywords":["忠實","大德奏功","富貴榮達"],"text":"權威顯達、吉人天相數。天稟溫和忠實，獨行而有權威，大德奏功之象。此數之人不以巧取勝，而以誠信與德行取得眾望，故事業能步步得利，終建大業而享富榮。唯「獨行」二字亦是其病：事事自己扛，久之身心俱疲，若能容人、肯授權，則富貴可長保。"},
  "38": {"poem":"磨鐵成針","keywords":["宜專技","勤勉小成","統率不足"],"text":"磨鐵成針的意志薄弱數。統率之力不足，然若肯專一磨礪，亦能於一技一藝上成器。此數之人不宜爭強、不宜多頭，宜擇定一門技藝或專業深耕；勤勉可小成，急功則易敗。是「守得住就有」的一個數。"},
  "39": {"poem":"富貴榮華","keywords":["富貴","權威","長壽"],"text":"富貴榮華的變化無窮數。權威與財富俱盛，此數之人有雄才亦有雅量，能統眾而不失人心，故富貴長壽、家門昌隆，是八十一數中的上上之數。唯其中含有大變之機，盛極須防轉折；剛氣過盛時宜多經營人際與感情。"},
  "40": {"poem":"退安之數","keywords":["宜退守","投機易敗"],"text":"退安則吉、進取則凶數。智謀雖足而德望不稱，此數之人常有膽識與手腕，然易生投機之心，一旦冒進則敗。宜退守、宜穩健、宜安分守成；若肯以德濟才、少走捷徑，則可保平安，否則一生浮沉難定。"},
  "41": {"poem":"有德之數","keywords":["德望","才識","事業昌隆","名利雙收"],"text":"德望高大的有德之數。膽識、德望、才藝俱備，此數之人處事有分寸而待人有誠意，故事業昌隆、名利雙收，是純吉無雜之數。晚運尤佳，福澤亦及子孫。得此數者宜守其厚德，德在則福在。"},
  "42": {"poem":"寒蟬在柳","keywords":["博而不精","宜擇一專精"],"text":"寒蟬在柳的博而不精數。多才多藝而失之於雜，此數之人涉獵極廣、樣樣能通，卻少有一門做到極處，故常見「什麼都會、什麼都不精」之嘆。宜及早擇一專精，廣而不深終難成器。"},
  "43": {"poem":"散財破產","keywords":["散財","外華內虛","意志不堅"],"text":"散財破產的雨夜之花數。外表華美而內裡空虛，此數之人多有才藝與見識，然意志不堅、用度無節，錢財易聚亦易散；親緣薄、晚境多淒。若能自律節用、守住一份實業，尚可免於傾覆。"},
  "44": {"poem":"破家之數","keywords":["破家","災禍","愁眉難展"],"text":"愁眉難展的破家數。諸事不順、災禍疊來，此數之人縱有奇才亦每逢逆運，謀事屢遭中斷；家庭破散、病弱刑傷之事亦時見。極少數意志超群者能於逆境中轉出一片天，然對多數人而言宜守不宜攻、宜靜不宜動。"},
  "45": {"poem":"順風之數","keywords":["順風","智謀","大志得成","榮華"],"text":"順風揚帆的新生之數。智謀周備、經緯深奧，此數之人思慮縝密而識見深遠，能於大局中看清脈絡，故謀事多能順遂；中年後大志得成，榮華可期。若能戒驕戒躁，則一生少見逆流。"},
  "46": {"poem":"羅網離身","keywords":["羅網繫身","困苦","意志薄弱","能自立可轉"],"text":"羅網繫身的離祖成家數。一生困苦不離身之凶數，此數之人意志若薄，易走入歧途而受縲紲之辱，終身辛苦而多悲；然若能自立志氣、以仁義自持，則可離祖成家、於困境中轉出新局。是「全看意志」的一個數。"},
  "47": {"poem":"點石成金","keywords":["開花結果","天賦幸運","家門隆昌"],"text":"點石成金的開花結果數。天賦幸運、貴人自來，此數之人做事往往順水推舟即成，家門隆昌而子孫亦昌；財帛豐盈，是少見的福厚之數。晚運尤佳，得此數者宜多積德，福可久享。"},
  "48": {"poem":"古松立鶴","keywords":["德智兼備","師範","受人尊敬"],"text":"古松立鶴的德智兼備數。德望與智謀俱高，此數之人可為人師、可為人謀，處事有分寸而言語有分量，故受人尊敬而不樹敵；名利雖不必極盛，勝在長久穩當。是最適合走「專業與聲望」這條路的數。"},
  "49": {"poem":"轉變之數","keywords":["轉變","吉凶難分"],"text":"吉凶難分的轉變之數。此數含大轉折之機，遇吉則大吉、遇凶則大凶，全看他格配合與自身取捨。此數之人一生多逢分水嶺，一步走對滿盤皆活，一步走錯滿盤皆輸。"},
  "50": {"poem":"小舟入海","keywords":["一成一敗","盛衰交替","晚年宜防"],"text":"小舟入海的一成一敗數。盛衰交替之數，此數之人常有一次大成，亦常有一次大敗，先成後敗者尤多；中年前後是關口。宜在得意時預留退路、在失意時守住本分；晚年尤須防傾覆，安分則可保。"},
  "51": {"poem":"沉浮之數","keywords":["先盛後衰","榮枯無定","宜守成"],"text":"盛衰交加的沉浮之數。先盛後衰之象，此數之人早年多順、名利來得不難，然中年後漸見榮枯無定，若不早作打算，易於晚境落寞。宜守成不宜擴張、宜積蓄不宜揮霍，把前半生的勢穩住即是善策。"},
  "52": {"poem":"達眼之數","keywords":["先見之明","決斷","一舉成功"],"text":"先見之明的理想實現數。有先見之明、精幹之才，此數之人意志堅定而善於謀劃，能察時世、投機會，故常能於眾人未覺時搶先落子；他人以為難事，於其手中往往容易成就，終得名利雙全。"},
  "53": {"poem":"曲捲難伸","keywords":["外祥內患","盛衰參半"],"text":"外祥內患的盛衰參半數。外觀華美而內裡多憂，此數之人表面看去順遂，實則內有難言之患；前半生順者後半生多苦，前半生苦者後半生反安。宜早識其虛實，把外面的體面換成裡面的實底，方免虛耗。"},
  "54": {"poem":"石上栽花","keywords":["多難","憂悶","辛苦","難成"],"text":"石上栽花的多難數。憂悶困苦、辛苦難成，此數之人縱極盡努力亦每見徒勞，如石上栽花難以生根；親緣薄、身多病，晚景尤須留意。若他格得強吉相扶尚可減其凶，然大體宜守分、宜安命、勿強求。"},
  "55": {"poem":"善惡交集","keywords":["外美內苦","極盛還衰","宜堅忍"],"text":"善惡交集的極盛還衰數。外觀極美而內裡極苦，此數之人常被人羨而自知其難；表面的順遂之下藏著實際的困頓，且往往在最盛之時忽轉急下。唯以堅忍化之：肯吃常人不肯吃的苦、肯守常人不肯守的分，則外美之外亦得內實。"},
  "56": {"poem":"浪裡行舟","keywords":["事與願違","缺實行力","晚苦"],"text":"浪裡行舟的事與願違數。缺乏實行之力，此數之人多有想法而少有落實，事至臨門每見遲疑，故一生所願難償；晚境尤見困苦。若能補上「做完」這一環、少謀多行，仍可挽回相當一段，否則終是紙上功夫。"},
  "57": {"poem":"日照春松","keywords":["寒雪青松","苦盡甘來","時來運轉"],"text":"日照春松的寒雪青松數。雖有一時之大難，然天賦幸運，此數之人如寒雪中的青松，越是逆境越顯其質；中年前後必逢一次大關，過得去則後運大開，苦盡甘來而享榮華。是「熬得住就贏」的一個數。"},
  "58": {"poem":"晚行遇月","keywords":["先苦後甘","浮沉","晚年安泰"],"text":"晚行遇月的先苦後甘數。浮沉多端，此數之人前半生辛苦、屢遭挫折，家業亦有一度傾頹；然中年後漸入佳境，晚景安泰富裕。得此數者不必急於一時，把前半程當作積累，後半程自有回報。"},
  "59": {"poem":"寒蟬悲風","keywords":["寸進難伸","失意","缺乏勇氣"],"text":"寒蟬悲風的寸進難伸數。缺乏勇氣與耐力，此數之人一遇挫折即生退意，故雖有機會亦每每錯過；財帛難聚、家業難成，晚景多失意。若能於一處硬撐到底、把「再試一次」變成習慣，方有轉機。"},
  "60": {"poem":"黑暗無光","keywords":["無謀","動搖","方針不定"],"text":"黑暗無光的動搖不定數。無謀無策、方針不定，此數之人常在幾條路之間反覆，做一半又改，故一生勞碌而無所成；且易遭刑罰、病患與破財之厄。最要緊的不是選對，而是選定之後不再搖擺。"},
  "61": {"poem":"牡丹芙蓉","keywords":["名利雙收","宜克己","慎防驕慢"],"text":"牡丹芙蓉的名利雙收數。名利雙收、繁榮富貴，此數之人才華與機遇俱備，事業順遂而家門昌隆。唯其中含驕慢之機：得意易忘形、順境易輕人，若不克己自持，內部易生不和而毀於自身。"},
  "62": {"poem":"基礎虛弱","keywords":["內外不和","信用漸失"],"text":"基礎虛弱的內外不和數。根基不固、內外失和，此數之人外面看去尚可，內裡卻經不起考驗，一遇風波即見崩落；信用亦隨之漸失。宜先補根本、先修人和，把地基打實了再談發展。"},
  "63": {"poem":"富貴榮華","keywords":["萬物化育","子孫繁榮"],"text":"萬物化育的富貴榮華數。萬物化育、諸事順遂，此數之人身心健全、家庭圓滿，事業穩步而少見逆流，子孫亦繁榮，是純吉之數。得此數者少有大風大浪，宜守其和順，不必強爭。"},
  "64": {"poem":"骨肉分離","keywords":["沉滯","破敗"],"text":"骨肉分離的沉滯破敗數。災禍頻仍、骨肉分離，此數之人縱勤勉亦難敵其運，謀事屢遭破敗，親緣尤薄；病弱、破財之事亦時見。宜守分安命、少涉險局，且當以他格之吉相濟。"},
  "65": {"poem":"巨流歸海","keywords":["家運隆昌","富貴長壽"],"text":"巨流歸海的家運隆昌數。事事如意、家運隆昌，此數之人如江河歸海，行事自有其歸處，故富貴長壽而少見坎坷；上下和順，晚景尤豐。是八十一數中最安穩的吉數之一。"},
  "66": {"poem":"岩頭步馬","keywords":["內外不和","進退失據","災禍"],"text":"岩頭步馬的內外不和數。進退失據、內外不和，此數之人如在岩頭驅馬，前無路而後無援，謀事每於關鍵處失據；災禍與損耗亦多。宜大幅收縮、宜穩守本分，不宜同時開多條戰線。"},
  "67": {"poem":"通達之數","keywords":["通達","得提攜","自立成業"],"text":"通達順遂的自立成業數。事事通達、得長輩提攜，此數之人有獨立開創之力，亦能得外助，故家業漸興而名望漸隆；財帛豐盈，晚運尤佳。得此數者宜把握機遇，勿因安逸而止步。"},
  "68": {"poem":"順風揚帆","keywords":["思慮周密","勤勉","興家立業"],"text":"順風揚帆的興家立業數。思慮周密、勤勉務實，此數之人不靠投機而靠積累，故所成雖不迅疾卻極穩；創業、發明、經營皆有可觀，家業能立而能守。是最適合長線經營的數之一。"},
  "69": {"poem":"非業之數","keywords":["動搖不安","窮迫","病弱"],"text":"非業非命的動搖不安數。窮迫困頓、動搖不安，此數之人常處於「明知不對卻停不下來」的局面，謀事屢躓而身心俱疲；病弱之憂亦重。宜早斷早退、寧可少做，不可硬撐。"},
  "70": {"poem":"險惡之數","keywords":["慘淡","空虛","晚景淒涼"],"text":"慘淡空虛的險惡之數。空虛慘淡之象，此數之人一生多逢廢亡與損耗，縱有一時之得亦難留住；晚景尤見淒涼。唯以極穩健之姿守成，且早為晚年做打算，方能稍避其鋒。"},
  "71": {"poem":"石上金花","keywords":["內心勞苦","得貴人則成"],"text":"石上金花的內心勞苦數。外觀尚可而內心多苦，此數之人有相當的能力，然缺一股貫徹到底的勁，故常止於半途；若能得貴人相助、或與人合力，則可成事。是「獨力難成、合力可成」的一個數。"},
  "72": {"poem":"勞苦之數","keywords":["先甘後苦","苦樂參半"],"text":"先甘後苦的勞苦之數。苦樂參半，此數之人前半生多順、看似福厚，然中年後漸入辛勞，晚景困苦者多。宜在順境時即預留後路、節用積蓄，把好日子的餘裕留給難走的那一段。"},
  "73": {"poem":"志高力微","keywords":["天賦平安"],"text":"志高力微的天賦平安數。志向高遠而實行之力不足，此數之人常有超出能力的抱負，故大業難成；然天賦平安，衣食無缺、家庭和順，一生雖無大成亦無大禍。安於此，則是福。"},
  "74": {"poem":"殘菊逢霜","keywords":["沉淪","無為","坐食山空"],"text":"殘菊逢霜的沉淪之數。無為坐食、智謀不足，此數之人既少開創之力亦少守成之心，家業漸次消耗而無從補進；晚景尤困。若能勤補其拙、早立一技，尚可自養。"},
  "75": {"poem":"守分之數","keywords":["守分則吉","進取則凶"],"text":"守分則吉、進取則凶數。此數之人守則安、動則敗：安分守成可保平順，一旦冒進、擴張、投機則立見挫折。宜穩健、宜依附有力者共事，不宜獨當大局。認清這一點，即是此數最大的用處。"},
  "76": {"poem":"離散之數","keywords":["傾覆","離散","晚年或轉安"],"text":"傾覆離散的內外不和數。傾覆離散之象，此數之人前半生多逢破敗與骨肉分離，家業與身心俱受折損；然中年後若能立定志氣、重整旗鼓，晚年反可轉安。是先破後立的一個數。"},
  "77": {"poem":"半吉半凶","keywords":["苦樂參半"],"text":"半吉半凶的苦樂參半數。前半生得享福澤者後半生多苦，前半生辛苦者後半生反安，此數之人的關口通常在中年。宜早識其轉折之機：得意時不盡用其福，失意時不盡棄其志。"},
  "78": {"poem":"晚苦之數","keywords":["禍福參半","晚境困苦"],"text":"禍福參半的晚苦之數。中年前尚見發達，才智亦足，然此數之人晚境多困，福澤有其盡頭。宜在能積之時多積、在能立之時早立，把中年的餘力換成晚年的憑依。"},
  "79": {"poem":"雲頭望月","keywords":["身疲力盡","窮迫","信用盡失"],"text":"雲頭望月的身疲力盡數。窮迫困頓、信用漸失，此數之人縱有才亦難施展，做事每見虎頭蛇尾，久之為人所不信；財帛難聚、身心俱疲。宜先重建信用、先做小而實的事，方有轉機。"},
  "80": {"poem":"遁吉之數","keywords":["辛苦多難","宜早退守靜"],"text":"辛苦多難的遁吉之數。一生辛苦多難，此數之人若在世事中強爭，則處處碰壁；然若早退守靜、安於平淡，反能得一份清吉。是八十一數中唯一「退比進好」講得最明白的一個。"},
  "81": {"poem":"萬物回春","keywords":["還本歸元","尊貴繁榮"],"text":"萬物回春的還本歸元數。八十一為極數，還本歸元、復歸於一，故其吉與「1」同。此數之人尊貴繁榮、名利並至，家門昌隆而福澤綿長，是數理循環的圓滿收束。"},
};

